import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AccessibilityInfo, PanResponder, StyleSheet, View } from 'react-native';
import { Canvas, Group, Vertices } from '@shopify/react-native-skia';
import { useDerivedValue, useFrameCallback, useSharedValue } from 'react-native-reanimated';
import {
  beginShuffle, clampView, decodeBase64, evalMosaicFrame, makeFrame, makeState,
  zoomAbout,
  type MosaicFrame, type MosaicState, type MosaicView,
} from './mosaicMath';
import { MOSAIC_COLS, MOSAIC_ROWS, MOSAIC_PAINTINGS, type MosaicPainting } from './mosaic-data';

export type MosaicGalleryProps = {
  paintings?: MosaicPainting[];
  /** Controlled painting index. Omit (with defaultIndex) for uncontrolled. */
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  /** Fired with 'shuffle' when a transition starts. */
  onFeedback?: (event: 'shuffle', index: number) => void;
  width?: number;
  height?: number;
  label?: string;
  reducedMotion?: boolean;
  /** Runs the transition clock about four times slower. Ignored while Reduce Motion is on. */
  slowMotion?: boolean;
};

const GAP = 0.14; // grout line, fraction of a cell
const BEVEL = [1.13, 1.05, 0.95, 0.84]; // per-corner light: tl, tr, bl, br

function shadeVertex(packed: number, factor: number): string {
  'worklet';
  // Vertices colors must be color strings (see Skia's VerticesProps) - raw
  // uint32 numbers are silently dropped by the native materializer.
  // Self-contained on purpose: Reanimated captures a worklet's module-scope
  // bindings at the worklet's position in the module, so a const declared
  // below would be captured undefined (crash on device).
  const C = '0123456789abcdef';
  const r = Math.min(255, Math.round(((packed >> 16) & 255) * factor));
  const g = Math.min(255, Math.round(((packed >> 8) & 255) * factor));
  const b = Math.min(255, Math.round((packed & 255) * factor));
  return '#' + C[r >> 4] + C[r & 15] + C[g >> 4] + C[g & 15] + C[b >> 4] + C[b & 15];
}

export function MosaicGallery({ paintings = MOSAIC_PAINTINGS, index, defaultIndex = 0, onIndexChange, onFeedback, width = 340, height = 234, label = 'Mosaic gallery', reducedMotion, slowMotion = false }: MosaicGalleryProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const [internal, setInternal] = useState(defaultIndex);
  const shown = index ?? internal;
  const cols = MOSAIC_COLS, rows = MOSAIC_ROWS;
  const cellCount = cols * rows;
  const cell = Math.min(width / cols, height / rows);
  const fieldW = cell * cols;
  const fieldH = cell * rows;
  const offX = (width - fieldW) / 2;
  const offY = (height - fieldH) / 2;

  const decoded = useMemo(() => paintings.map(p => decodeBase64(p.colorsB64)), [paintings]);
  const st = useSharedValue<MosaicState>(makeState(Math.min(shown, paintings.length - 1), decoded[Math.min(shown, paintings.length - 1)], cellCount));
  const frame: MosaicFrame = useMemo(() => makeFrame(cellCount), [cellCount]);
  const clock = useSharedValue(0);
  const reduceM = useSharedValue(false);
  const slowM = useSharedValue(false);
  const view = useSharedValue<MosaicView>({ scale: 1, tx: 0, ty: 0 });
  const latest = useRef({ paintings, shown, onIndexChange, onFeedback, reduce, decoded });
  latest.current = { paintings, shown, onIndexChange, onFeedback, reduce, decoded };

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then(v => { if (alive) setSystemReduce(v); }).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setSystemReduce);
    return () => { alive = false; sub.remove(); };
  }, []);
  useEffect(() => { reduceM.value = reduce; }, [reduce, reduceM]);
  useEffect(() => { slowM.value = slowMotion; }, [slowMotion, slowM]);

  // Rebuild state when the painting set changes (must stay stable per mount).
  useEffect(() => {
    const idx = Math.min(shown, decoded.length - 1);
    st.value = makeState(idx, decoded[idx], cellCount);
  }, [decoded, cellCount, st]); // eslint-disable-line react-hooks/exhaustive-deps

  const goTo = useCallback((next: number, gx: number, gy: number) => {
    const { paintings: ps, decoded: dec, onIndexChange: cb, onFeedback: fb } = latest.current;
    if (ps.length < 2) return;
    const target = ((next % ps.length) + ps.length) % ps.length;
    const seed = (target + 1) * 7919 + Math.floor(gx * 13 + gy * 17);
    // Mutate the shareable on the JS thread; worklets see the same object.
    beginShuffle(st.value, target, dec[target], clock.value, gx, gy, seed);
    if (index === undefined) setInternal(target);
    cb?.(target);
    fb?.('shuffle', target);
  }, [index, st, clock]);

  // Tap / double-tap / pan / pinch through one PanResponder (no gesture-handler dep).
  const originRef = useRef({ x: 0, y: 0 }); // canvas origin in page coords
  const pan = useMemo(() => {
    let startT = 0;
    let startX = 0;
    let startY = 0;
    let moved = false;
    let pinching = false;
    let lastTapT = 0;
    let baseView: MosaicView = { scale: 1, tx: 0, ty: 0 };
    let baseDist = 0;
    let baseMid = { x: 0, y: 0 };
    const dist = (touches: any[]) => Math.hypot(touches[0].pageX - touches[1].pageX, touches[0].pageY - touches[1].pageY);
    const mid = (touches: any[]) => ({ x: (touches[0].pageX + touches[1].pageX) / 2, y: (touches[0].pageY + touches[1].pageY) / 2 });
    // Canvas-local coords of a page point.
    const local = (px: number, py: number) => ({ x: px - originRef.current.x, y: py - originRef.current.y });
    return PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        const t = evt.nativeEvent;
        startT = Date.now();
        startX = t.pageX; startY = t.pageY;
        moved = false; pinching = false;
        baseView = { ...view.value };
      },
      onPanResponderMove: (evt) => {
        const touches = evt.nativeEvent.touches;
        if (touches.length >= 2) {
          const d = dist(touches);
          const m = mid(touches);
          if (!pinching) { pinching = true; baseDist = d; baseMid = m; baseView = { ...view.value }; return; }
          // Pan by midpoint delta, then zoom about the current midpoint.
          const pannedView = { scale: baseView.scale, tx: baseView.tx + (m.x - baseMid.x), ty: baseView.ty + (m.y - baseMid.y) };
          const f = local(m.x, m.y);
          view.value = zoomAbout(pannedView, baseView.scale * (d / Math.max(1, baseDist)), f.x, f.y, width, height);
          return;
        }
        const dx = evt.nativeEvent.pageX - startX;
        const dy = evt.nativeEvent.pageY - startY;
        if (Math.abs(dx) + Math.abs(dy) > 8) moved = true;
        if (moved) view.value = clampView({ scale: view.value.scale, tx: baseView.tx + dx, ty: baseView.ty + dy }, width, height);
      },
      onPanResponderRelease: (evt) => {
        if (pinching) { pinching = false; return; }
        if (!moved && Date.now() - startT < 300) {
          const now = Date.now();
          const lx = evt.nativeEvent.locationX;
          const ly = evt.nativeEvent.locationY;
          if (now - lastTapT < 320) {
            // Double tap: toggle a 2x zoom about the tap point.
            const v = view.value;
            view.value = v.scale > 1.2 ? { scale: 1, tx: 0, ty: 0 } : zoomAbout(v, 2, lx, ly, width, height);
            lastTapT = 0;
            return;
          }
          lastTapT = now;
          const { shown: cur } = latest.current;
          // Tap origin in grid units for the ripple wave: invert the canvas transform.
          const v = view.value;
          const gx = (((lx - width / 2 - v.tx) / v.scale + width / 2) - offX) / cell;
          const gy = (((ly - height / 2 - v.ty) / v.scale + height / 2) - offY) / cell;
          goTo(cur + 1, Math.max(0, Math.min(cols, gx)), Math.max(0, Math.min(rows, gy)));
        }
      },
    });
  }, [view, width, height, offX, offY, cell, cols, rows, goTo]);
  const containerRef = useRef<View>(null);

  useFrameCallback((info) => {
    const prev = clock.value;
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    const scale = slowM.value && !reduceM.value ? 0.25 : 1;
    clock.value = prev + dt * scale;
    evalMosaicFrame(st.value, cols, rows, clock.value, reduceM.value, frame);
  });

  const indices = useMemo(() => {
    const idx: number[] = [];
    for (let i = 0; i < cellCount; i++) {
      const b = i * 4;
      idx.push(b, b + 1, b + 2, b + 2, b + 1, b + 3);
    }
    return idx;
  }, [cellCount]);

  const vertices = useDerivedValue(() => {
    clock.value; // recompute per frame
    const out = new Array<{ x: number; y: number }>(cellCount * 4);
    const half = (cell * (1 - GAP)) / 2;
    for (let i = 0; i < cellCount; i++) {
      const cx = offX + frame.x[i] * cell;
      const cy = offY + frame.y[i] * cell;
      const h = half * frame.s[i];
      const o = i * 4;
      out[o] = { x: cx - h, y: cy - h };
      out[o + 1] = { x: cx + h, y: cy - h };
      out[o + 2] = { x: cx - h, y: cy + h };
      out[o + 3] = { x: cx + h, y: cy + h };
    }
    return out;
  });

  const vcolors = useDerivedValue(() => {
    clock.value;
    const out = new Array(cellCount * 4);
    for (let i = 0; i < cellCount; i++) {
      const c = frame.color[i];
      const o = i * 4;
      out[o] = shadeVertex(c, BEVEL[0]);
      out[o + 1] = shadeVertex(c, BEVEL[1]);
      out[o + 2] = shadeVertex(c, BEVEL[2]);
      out[o + 3] = shadeVertex(c, BEVEL[3]);
    }
    return out;
  });

  const transform = useDerivedValue(() => {
    const v = view.value;
    return [{ translateX: width / 2 + v.tx }, { translateY: height / 2 + v.ty }, { scale: v.scale }, { translateX: -width / 2 }, { translateY: -height / 2 }];
  });

  return (
    <View
      ref={containerRef}
      accessibilityLabel={label}
      accessibilityRole="image"
      style={[styles.wrap, { width, height }]}
      onLayout={() => containerRef.current?.measure((_x, _y, _w, _h, px, py) => { originRef.current = { x: px, y: py }; })}
      {...pan.panHandlers}
    >
      <Canvas style={StyleSheet.absoluteFill}>
        <Group transform={transform}>
          <Vertices vertices={vertices} colors={vcolors} indices={indices} />
        </Group>
      </Canvas>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { borderRadius: 16, overflow: 'hidden', backgroundColor: '#101c15' },
});

export default MosaicGallery;

/**
 * mosaicMath.ts - pure, worklet-safe math for MosaicGallery.
 *
 * Everything here is deterministic and shared verbatim between the native
 * Skia renderer and the web Canvas2D preview. No DOM, no Skia, no Reanimated
 * imports; the same file runs in Node for tests.
 */

export interface MosaicFrame {
  /** Center x per cell, in grid units (0..cols). */
  x: Float32Array;
  /** Center y per cell, in grid units (0..rows). */
  y: Float32Array;
  /** Uniform scale per cell (1 = rest size). */
  s: Float32Array;
  /** Packed 0xFFRRGGBB color per cell. */
  color: Uint32Array;
}

export interface MosaicState {
  /** Resting slot per cell in the currently shown painting. */
  home: Uint16Array;
  /** Slot each cell started the active transition from. */
  from: Uint16Array;
  /** Slot each cell is flying to in the active transition. */
  to: Uint16Array;
  /** RGB888 colors of the outgoing painting. */
  colorsA: Uint8ClampedArray;
  /** RGB888 colors of the incoming painting. */
  colorsB: Uint8ClampedArray;
  /** Index of the painting shown (or being left). */
  painting: number;
  /** Index of the painting being entered. */
  nextPainting: number;
  /** Clock time the transition started, in seconds. */
  startT: number;
  /** Tap origin of the transition, in grid units. */
  ox: number;
  oy: number;
  /** Seed for the shuffle permutation and per-cell jitter. */
  seed: number;
  /** 1 while a transition is in flight. */
  active: 0 | 1;
}

export const SHUFFLE_DURATION = 0.62; // seconds per cell
export const SHUFFLE_SPREAD = 0.55; // radial stagger span, seconds
export const SHUFFLE_JITTER = 0.14; // random extra stagger, seconds
export const ARC_AMOUNT = 2.6; // mid-flight scatter, grid units
export const POP_SCALE = 0.55; // mid-flight growth

/* ---------------------------------------------------------------- rng */

export function hashSeed(n: number): number {
  'worklet';
  let h = (n | 0) ^ 0x9e3779b9;
  h = Math.imul(h ^ (h >>> 16), 0x21f0aaad);
  h = Math.imul(h ^ (h >>> 15), 0x735a2d97);
  return (h ^ (h >>> 15)) >>> 0;
}

/** Deterministic pseudo-random in [0, 1) for an integer stream position. */
export function rand01(stream: number): number {
  'worklet';
  return hashSeed(stream) / 4294967296;
}

/* ------------------------------------------------------------ base64 */

const B64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Worklet-safe base64 decode (no atob on Hermes). */
export function decodeBase64(b64: string): Uint8ClampedArray {
  'worklet';
  let len = b64.length;
  while (len > 0 && b64.charCodeAt(len - 1) === 61) len--; // strip '='
  const out = new Uint8ClampedArray(Math.floor((len * 3) / 4));
  let acc = 0;
  let bits = 0;
  let o = 0;
  for (let i = 0; i < len; i++) {
    const v = B64_CHARS.indexOf(b64[i]);
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[o++] = (acc >> bits) & 0xff;
    }
  }
  return out;
}

/* ---------------------------------------------------------- shuffling */

/** Fisher-Yates permutation of [0, n), seeded. perm[i] = target slot. */
export function shufflePermutation(n: number, seed: number): Uint16Array {
  'worklet';
  const perm = new Uint16Array(n);
  for (let i = 0; i < n; i++) perm[i] = i;
  let s = hashSeed(seed);
  for (let i = n - 1; i > 0; i--) {
    s = hashSeed(s + i);
    const j = s % (i + 1);
    const tmp = perm[i];
    perm[i] = perm[j];
    perm[j] = tmp;
  }
  return perm;
}

/* ------------------------------------------------------------ easing */

export function clamp01(v: number): number {
  'worklet';
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

export function easeInOutCubic(p: number): number {
  'worklet';
  return p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2;
}

export function easeOutQuad(p: number): number {
  'worklet';
  return 1 - (1 - p) * (1 - p);
}

/* --------------------------------------------------------- transitions */

/**
 * Per-cell stagger delay: a radial wave out from the tap point plus jitter,
 * so the shuffle ripples across the field instead of flipping at once.
 */
export function cellDelay(slot: number, cols: number, rows: number, ox: number, oy: number, seed: number): number {
  'worklet';
  const cx = (slot % cols) + 0.5;
  const cy = Math.floor(slot / cols) + 0.5;
  const dx = cx - ox;
  const dy = cy - oy;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const diag = Math.sqrt(cols * cols + rows * rows) * 0.5;
  return (dist / diag) * SHUFFLE_SPREAD + rand01(seed * 31 + slot * 7) * SHUFFLE_JITTER;
}

export function makeState(painting: number, colors: Uint8ClampedArray, cellCount: number): MosaicState {
  const home = new Uint16Array(cellCount);
  for (let i = 0; i < cellCount; i++) home[i] = i;
  return {
    home,
    from: home.slice(),
    to: home.slice(),
    colorsA: colors,
    colorsB: colors,
    painting,
    nextPainting: painting,
    startT: 0,
    ox: 0,
    oy: 0,
    seed: 0,
    active: 0,
  };
}

/**
 * Begin a shuffle to `nextPainting`. Cell i flies from its current resting
 * slot to perm[i]; when it lands it shows colorsB[perm[i]].
 */
export function beginShuffle(
  st: MosaicState,
  nextPainting: number,
  colorsB: Uint8ClampedArray,
  now: number,
  ox: number,
  oy: number,
  seed: number,
): void {
  'worklet';
  const n = st.home.length;
  const perm = shufflePermutation(n, seed);
  st.from.set(st.home);
  st.to.set(perm);
  st.colorsB = colorsB;
  st.nextPainting = nextPainting;
  st.startT = now;
  st.ox = ox;
  st.oy = oy;
  st.seed = seed;
  st.active = 1;
}

/**
 * Evaluate one frame. Positions are in grid units; the renderer multiplies
 * by the cell size. When `reduced` is set the ripple becomes a quick global
 * crossfade with no flight.
 */
export function evalMosaicFrame(
  st: MosaicState,
  cols: number,
  rows: number,
  t: number,
  reduced: boolean,
  out: MosaicFrame,
): void {
  'worklet';
  const n = st.home.length;
  if (reduced) {
    // Positions never move and the permutation is ignored: each cell stays
    // on its resting slot and crossfades to the new painting in 240 ms.
    const p = st.active ? clamp01((t - st.startT) / 0.24) : 1;
    if (st.active && p >= 1) {
      st.colorsA = st.colorsB;
      st.painting = st.nextPainting;
      st.active = 0;
    }
    const A2 = st.colorsA;
    const B2 = st.colorsB;
    for (let i = 0; i < n; i++) {
      const slot = st.home[i];
      out.x[i] = (slot % cols) + 0.5;
      out.y[i] = Math.floor(slot / cols) + 0.5;
      out.s[i] = 1;
      const si = slot * 3;
      const r = A2[si] + (B2[si] - A2[si]) * p;
      const g = A2[si + 1] + (B2[si + 1] - A2[si + 1]) * p;
      const b = A2[si + 2] + (B2[si + 2] - A2[si + 2]) * p;
      out.color[i] = 0xff000000 | (((r | 0) & 255) << 16) | (((g | 0) & 255) << 8) | ((b | 0) & 255);
    }
    return;
  }

  let allDone = true;
  const A = st.colorsA;
  const B = st.colorsB;
  for (let i = 0; i < n; i++) {
    const fromSlot = st.from[i];
    const toSlot = st.to[i];
    let p = 1;
    if (st.active) {
      const delay = cellDelay(fromSlot, cols, rows, st.ox, st.oy, st.seed);
      p = clamp01((t - st.startT - delay) / SHUFFLE_DURATION);
      if (p < 1) allDone = false;
      p = easeInOutCubic(p);
    }
    const fx = (fromSlot % cols) + 0.5;
    const fy = Math.floor(fromSlot / cols) + 0.5;
    const tx = (toSlot % cols) + 0.5;
    const ty = Math.floor(toSlot / cols) + 0.5;
    const flight = st.active ? Math.sin(Math.PI * clamp01(p)) : 0;
    const r1 = rand01(st.seed * 131 + i * 17) - 0.5;
    const r2 = rand01(st.seed * 733 + i * 29) - 0.5;
    out.x[i] = fx + (tx - fx) * p + r1 * ARC_AMOUNT * 2 * flight;
    out.y[i] = fy + (ty - fy) * p + r2 * ARC_AMOUNT * 2 * flight;
    out.s[i] = 1 + POP_SCALE * flight;
    const ai = fromSlot * 3;
    const bi = toSlot * 3;
    const cr = A[ai] + (B[bi] - A[ai]) * p;
    const cg = A[ai + 1] + (B[bi + 1] - A[ai + 1]) * p;
    const cb = A[ai + 2] + (B[bi + 2] - A[ai + 2]) * p;
    out.color[i] = 0xff000000 | (((cr | 0) & 255) << 16) | (((cg | 0) & 255) << 8) | ((cb | 0) & 255);
  }
  if (st.active && allDone) {
    st.home.set(st.to);
    st.colorsA = st.colorsB;
    st.painting = st.nextPainting;
    st.active = 0;
  }
}

/** Allocate the frame buffers for `cellCount` cells. */
export function makeFrame(cellCount: number): MosaicFrame {
  return {
    x: new Float32Array(cellCount),
    y: new Float32Array(cellCount),
    s: new Float32Array(cellCount),
    color: new Uint32Array(cellCount),
  };
}

/* ------------------------------------------------------ view transform */

export interface MosaicView {
  scale: number;
  tx: number;
  ty: number;
}

export const MIN_ZOOM = 1;
export const MAX_ZOOM = 6;

/** Clamp and re-center so the field never leaves the viewport. */
export function clampView(view: MosaicView, width: number, height: number): MosaicView {
  'worklet';
  const scale = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, view.scale));
  const maxTx = (width * (scale - 1)) / 2;
  const maxTy = (height * (scale - 1)) / 2;
  return {
    scale,
    tx: Math.min(maxTx, Math.max(-maxTx, view.tx)),
    ty: Math.min(maxTy, Math.max(-maxTy, view.ty)),
  };
}

/** Zoom about a focal point: keeps the point under the fingers stationary. */
export function zoomAbout(view: MosaicView, nextScale: number, fx: number, fy: number, width: number, height: number): MosaicView {
  'worklet';
  const scale = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, nextScale));
  if (scale === view.scale) return view;
  const cx = width / 2;
  const cy = height / 2;
  // Field point under the focal point, in unscaled coords.
  const px = (fx - cx - view.tx) / view.scale;
  const py = (fy - cy - view.ty) / view.scale;
  return clampView({ scale, tx: fx - cx - px * scale, ty: fy - cy - py * scale }, width, height);
}

import React, { useCallback, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { MosaicGallery, type MosaicGalleryProps } from './MosaicGallery';
import { MOSAIC_PAINTINGS } from './mosaic-data';

export default function Example({ onFeedback }: { onFeedback?: MosaicGalleryProps['onFeedback'] }) {
  const [index, setIndex] = useState(0);
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState<boolean | undefined>();
  const painting = MOSAIC_PAINTINGS[index];
  const onChange = useCallback((i: number) => setIndex(i), []);
  return (
    <View style={{ paddingVertical: 24, width: '100%', alignItems: 'center' }}>
      <Text accessibilityLiveRegion="polite" style={{ color: '#31513b', fontSize: 13, marginBottom: 4 }}>
        {painting.title} · {painting.artist}, {painting.year}
      </Text>
      <MosaicGallery label={`Mosaic of ${painting.title} by ${painting.artist}`} index={index} onIndexChange={onChange} slowMotion={slow} reducedMotion={reduce} onFeedback={onFeedback} />
      <Text style={{ color: '#4b6053', fontSize: 12, marginTop: 16 }}>Tap the mosaic for the next painting. Pinch to zoom, double-tap to zoom in.</Text>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', gap: 8, marginTop: 10 }}>
        <Pressable accessibilityRole="button" accessibilityLabel="Next painting" onPress={() => setIndex((index + 1) % MOSAIC_PAINTINGS.length)} style={{ minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#31513b', justifyContent: 'center' }}><Text style={{ color: '#f3f6ee', fontSize: 13 }}>Next painting</Text></Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} accessibilityLabel="Slow motion" onPress={() => setSlow(!slow)} style={{ minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#e6edde', justifyContent: 'center' }}><Text style={{ color: '#31513b', fontSize: 13 }}>Slow motion: {slow ? 'on' : 'off'}</Text></Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce === true }} accessibilityLabel="Reduced motion" onPress={() => setReduce(reduce === true ? undefined : true)} style={{ minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#e6edde', justifyContent: 'center' }}><Text style={{ color: '#31513b', fontSize: 13 }}>Motion: {reduce === true ? 'reduced' : 'system'}</Text></Pressable>
      </View>
    </View>
  );
}
